package co.kr.badara.dolswevoice;
import android.app.*;import android.content.*;import android.content.pm.*;import android.location.*;import android.os.*;import java.io.*;import java.lang.reflect.*;import org.json.*;
/** Emulator-only integration: changes mock network provider and test preferences. */
public final class AndroidHomeUpdateTests extends Instrumentation {
 int checks;void ok(boolean condition){checks++;if(!condition)throw new AssertionError("Android check "+checks);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle report=new Bundle();HomeGate gate=null;LocationManager lm=null;try{Context ctx=getTargetContext();Config cfg=new Config(ctx);cfg.p.edit().putBoolean("homeOnly",true).putBoolean("homeSet",true).putLong("homeLat",Double.doubleToLongBits(37.5)).putLong("homeLon",Double.doubleToLongBits(127)).putInt("homeRadius",200).commit();lm=ctx.getSystemService(LocationManager.class);lm.addTestProvider(LocationManager.NETWORK_PROVIDER,false,false,false,false,true,true,true,Criteria.POWER_LOW,Criteria.ACCURACY_FINE);lm.setTestProviderEnabled(LocationManager.NETWORK_PROVIDER,true);ctx.startForegroundService(new Intent(ctx,VoiceService.class).putExtra("mode","test"));Thread.sleep(800);gate=new HomeGate(ctx,cfg);ok(gate.enabled()&&gate.configured());gate.start();Location inside=new Location(LocationManager.NETWORK_PROVIDER);inside.setLatitude(37.5);inside.setLongitude(127);inside.setAccuracy(10);inside.setTime(System.currentTimeMillis());inside.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());lm.setTestProviderLocation(LocationManager.NETWORK_PROVIDER,inside);Thread.sleep(1200);if(!gate.inside())throw new AssertionError("No inside update: "+gate.status()+" last="+lm.getLastKnownLocation(LocationManager.NETWORK_PROVIDER));ok(true);android.media.AudioManager audio=ctx.getSystemService(android.media.AudioManager.class);for(int attempt=0;attempt<20&&audio.getActiveRecordingConfigurations().isEmpty();attempt++)Thread.sleep(500);ok(!audio.getActiveRecordingConfigurations().isEmpty());Location outside=new Location(inside);outside.setLatitude(37.6);outside.setTime(System.currentTimeMillis());outside.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());for(int attempt=0;attempt<130&&gate.inside();attempt++){outside.setTime(System.currentTimeMillis());outside.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());lm.setTestProviderLocation(LocationManager.NETWORK_PROVIDER,outside);Thread.sleep(1000);}ok(!gate.inside());for(int attempt=0;attempt<10&&!audio.getActiveRecordingConfigurations().isEmpty();attempt++)Thread.sleep(200);ok(audio.getActiveRecordingConfigurations().isEmpty());gate.stop();cfg.p.edit().putBoolean("homeOnly",false).commit();ok(gate.inside());
  final Activity[] fake={null};runOnMainSync(()->fake[0]=new Activity(){public PackageManager getPackageManager(){return ctx.getPackageManager();}public String getPackageName(){return ctx.getPackageName();}});AppUpdates updater=new AppUpdates(fake[0]);Method verify=AppUpdates.class.getDeclaredMethod("verify",File.class,UpdateSpec.class);verify.setAccessible(true);File candidate=new File(ctx.getCacheDir(),"test-future.apk");try(InputStream in=getContext().getAssets().open("future.apk");OutputStream out=new FileOutputStream(candidate)){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);}String metadata=new JSONObject().put("versionCode",7).put("versionName","1.1.2").put("apkUrl",UpdateSpec.REPOSITORY+"/releases/download/v1.1.2/dolswe-voice.apk").put("size",candidate.length()).put("sha256",AppUpdates.sha(candidate)).toString();verify.invoke(updater,candidate,new UpdateSpec(metadata));ok(true);JSONObject invalid=new JSONObject(metadata).put("versionCode",8);boolean rejected=false;try{verify.invoke(updater,candidate,new UpdateSpec(invalid.toString()));}catch(InvocationTargetException error){rejected=true;}ok(rejected);candidate.delete();updater.close();
  report.putString("stream","ANDROID_HOME_UPDATE_OK "+checks+" checks: mock home enter/exit, gate disabled, matching APK signer, rejected version mismatch");finish(Activity.RESULT_OK,report);
 }catch(Throwable e){report.putString("stream","ANDROID_HOME_UPDATE_FAIL after "+checks+" checks: "+e);finish(Activity.RESULT_CANCELED,report);}finally{getTargetContext().stopService(new Intent(getTargetContext(),VoiceService.class));if(gate!=null)gate.stop();if(lm!=null)try{lm.removeTestProvider(LocationManager.NETWORK_PROVIDER);}catch(Exception ignored){}getTargetContext().getSharedPreferences("voice",0).edit().clear().commit();}}
}
